/*
 * io_$build_dcte_list - Build IO_$DCTE_LIST
 *
 * Original address: 0x00E32834 (was FUN_00e32834; the first routine of the
 * SAU2 map's "I E32834 IO_ size = 22C" code segment, no symbol of its own)
 * Size: 170 bytes (0x00E32834 .. 0x00E328DF)
 * Generated by: Claude Opus 5.5
 *
 * Called only by IO_$INIT (0x00E32920).  Links the DCTEs of the dynamic
 * DCTE area (variable-length records, each length rounded up to 8) and then
 * the static DCTEs DEV_DCTES names into one list, and stores its head.
 *
 * Frame (link.w A6,-0x5c; A2 saved): a dummy DCTE at (-0x48,A6) whose
 * nextp (-0x40,A6) becomes the head; A0 the last DCTE linked.
 *
 * Blocks:
 *   0x00E3283A-0x00E328A2  while more than 8 bytes of the area remain: a
 *                          zero length is "bad dcte length" and ends the
 *                          walk (unlinked); a length that is not a multiple
 *                          of 8 is "bad dcte length" but linked; else status
 *                          0; step by the rounded length
 *   0x00E328A4-0x00E328CA  append every DEV_DCTES entry up to the nil
 *   0x00E328CC-0x00E328D2  IO_$DCTE_LIST = the head
 *
 * Quirks reproduced:
 *   - The area test is `end - next > 8' (unsigned), so a trailing record of
 *     8 bytes or less is never looked at.
 */

#include "io/io_internal.h"

/* `cmpi.l #0x8,D1` / `bhi` 0x00E3289C */
#define IO_DCTE_AREA_SLACK  8

void io_$build_dcte_list(void)
{
    dcte_t *head;                       /* (-0x40,A6), the dummy's nextp */
    dcte_t **link;                      /* A0 + 8 */
    dcte_t *d;                          /* A1 */
    uint32_t next;                      /* D0 */
    int32_t k;                          /* D1 / 4 */

    /* 0x00E3283A-0x00E328A2 */
    head = NULL;
    link = &head;
    next = io_$dcte_area_start;
    while (io_$dcte_area_end - next > IO_DCTE_AREA_SLACK) {
        d = (dcte_t *)ARCH_VA_TO_PTR(next);
        if (d->length == 0) {
            d->cstatus = status_$io_bad_dcte_length;
            break;
        }
        if ((d->length & 7) != 0) {
            d->cstatus = status_$io_bad_dcte_length;
        } else {
            d->cstatus = status_$ok;
        }
        d->nextp = NULL;
        *link = d;
        link = &d->nextp;
        next += ((uint32_t)d->length + 7) & ~7u;
    }

    /* 0x00E328A4-0x00E328CA */
    for (k = 0; DEV_DCTES[k] != NULL; k++) {
        d = DEV_DCTES[k];
        d->nextp = NULL;
        *link = d;
        link = &d->nextp;
    }

    /* 0x00E328CC-0x00E328D2 */
    IO_$DCTE_LIST = head;
}
